  return [null, msg, msg];
}

if (pending?.submittedBy?.phoneNorm === ctx.phone) {
  msg.statusCode = 409;
  msg.headers = { "Content-Type": "application/json; charset=utf-8" };
  msg.payload = { error: 'Result should be disputed by opposite team player' };
  return [null, msg, msg];
}

const teamA = asArray(pending?.teams?.teamA);
const teamB = asArray(pending?.teams?.teamB);
if (teamA.length === 0 || teamB.length === 0) {
  msg.statusCode = 409;
  msg.headers = { "Content-Type": "application/json; charset=utf-8" };
  msg.payload = { error: 'Pending result has invalid teams' };
  return [null, msg, msg];
}

const submittedByTeam = pending?.submittedByTeam === 'A' || pending?.submittedByTeam === 'B'
  ? pending.submittedByTeam
  : teamA.some((p) => p.phoneNorm === pending?.submittedBy?.phoneNorm)
    ? 'A'
    : teamB.some((p) => p.phoneNorm === pending?.submittedBy?.phoneNorm)
      ? 'B'
      : null;
const disputerTeam = teamA.some((p) => p.phoneNorm === ctx.phone)
  ? 'A'
  : teamB.some((p) => p.phoneNorm === ctx.phone)
    ? 'B'
    : null;

if (!submittedByTeam || !disputerTeam || submittedByTeam === disputerTeam) {
  msg.statusCode = 409;
  msg.headers = { "Content-Type": "application/json; charset=utf-8" };
  msg.payload = { error: 'Only the opposite team can dispute result' };
  return [null, msg, msg];
}

const submittedAtTs = Number(pending?.submittedAtTs || pending?.createdTs || 0);
const disputeDeadlineTsRaw = Number(pending?.disputeDeadlineTs || 0);
const disputeDeadlineTs =
  Number.isFinite(disputeDeadlineTsRaw) && disputeDeadlineTsRaw > 0
    ? disputeDeadlineTsRaw
    : Number.isFinite(submittedAtTs) && submittedAtTs > 0
      ? submittedAtTs + DISPUTE_WINDOW_MS
      : null;

if (Number.isFinite(disputeDeadlineTs) && disputeDeadlineTs <= Date.now()) {
  msg.statusCode = 409;
  msg.headers = { "Content-Type": "application/json; charset=utf-8" };
  msg.payload = { error: 'Dispute window has expired' };
  return [null, msg, msg];
}

const phones = uniq([
  ...teamA.map((p) => p.phoneNorm),
  ...teamB.map((p) => p.phoneNorm),
]);

msg._resultPending = Object.assign({}, pending, {
  submittedByTeam,
  disputeDeadlineTs,
});
msg.payload = { phoneNorm: { $in: phones } };
return [msg, null, msg];

const asArray = (v) => Array.isArray(v) ? v : [];

const ctx = msg._resultConfirm || {};
const pending = msg._resultPending || null;
if (!pending) {
  msg.statusCode = 409;
  msg.headers = { "Content-Type": "application/json; charset=utf-8" };
  msg.payload = { error: 'No pending result context' };
  return [null, null, null, msg, msg];
}

const now = new Date();
const nowIso = now.toISOString();
const nowTs = now.getTime();

const teamA = asArray(pending?.teams?.teamA);
const teamB = asArray(pending?.teams?.teamB);
const disputers = pending?.submittedByTeam === 'A' ? teamB : teamA;
const disputer = disputers.find((p) => p.phoneNorm === ctx.phone) || { id: null, name: 'Игрок', phoneNorm: ctx.phone };

const resultUpdateMsg = Object.assign({}, msg, {
  query: { id: pending.id, status: { $in: ['PENDING_CONFIRMATION', 'PENDING_DISPUTE'] } },
  payload: {
    $set: {
      status: 'DISPUTED',
      disputedBy: {
        id: disputer.id,
        name: disputer.name,
        phoneNorm: disputer.phoneNorm,
      },
      disputedAt: nowIso,
      disputedAtTs: nowTs,
      confirmedBy: null,
      confirmedAt: null,
      confirmedAtTs: null,
      ratingImpact: null,
      updatedAt: nowIso,
    },
  },
});

const gameUpdateMsg = Object.assign({}, msg, {
  query: { id: ctx.game?.id || pending.gameId },
  payload: {
    $set: {
      resultStatus: 'DISPUTED',
      resultId: pending.id,
      lastResultAt: nowIso,
      updatedAt: nowIso,
    },
  },
});

const responseMsg = Object.assign({}, msg, {
  statusCode: 200,
  headers: { "Content-Type": "application/json; charset=utf-8" },
  payload: {
    gameId: ctx.game?.id || pending.gameId,
    resultId: pending.id,
    status: 'DISPUTED',
    disputedAt: nowIso,
  },
});

const ratingsMsg = Object.assign({}, msg, { payload: [] });

return [resultUpdateMsg, ratingsMsg, gameUpdateMsg, responseMsg, responseMsg];

const item = msg.payload;
if (!item || typeof item !== 'object') return null;
msg.query = item.query;
msg.payload = item.update;
return msg;
